QUESTIONS.push(
{"id": "DL2-001", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-acetylcholine-nic", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Acetylcholine acts at the neuromuscular junction as which of the following?", "options": [{"t": "A depolarizing direct agonist", "correct": true, "why": "Acetylcholine opens the muscle nicotinic (Nm) channel and depolarizes the end plate; it is listed with succinylcholine as a depolarizing agent."}, {"t": "A non-depolarizing competitive antagonist", "correct": false, "why": "That is the curare-like drugs (rocuronium, vecuronium, pancuronium), which stop the channel from opening."}, {"t": "An indirect antagonist of acetylcholinesterase", "correct": false, "why": "That is neostigmine, pyridostigmine and the other cholinesterase inhibitors; they raise acetylcholine rather than being it."}, {"t": "An inhibitor of acetylcholine release", "correct": false, "why": "That is botulinum toxin, which acts on the presynaptic terminal."}, {"t": "A partial agonist at α4β2 receptors", "correct": false, "why": "That is varenicline, at the neuronal nicotinic (Nn) receptor in the brain."}], "teach": "The neuromuscular junction drugs split into direct and indirect. Direct drugs bind the muscle nicotinic (Nm) receptor: depolarizing agents are agonists (acetylcholine and succinylcholine); non-depolarizing agents are competitive antagonists (curare-like drugs). Indirect drugs block acetylcholinesterase and raise synaptic acetylcholine.", "quote": "Direct => Binding to the NM. Depolarizing agents Direct Agonist (Acetylcholine & Succinylcholine). Non-depolarizing agents Direct Antagonism (Curare like drugs)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 12"},
{"id": "DL2-002", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-varenicline", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of varenicline?", "options": [{"t": "Partial agonist at α4β2 neuronal nicotinic (Nn) receptors", "correct": true, "why": "Varenicline is a selective partial agonist at the central α4β2 Nn receptor, with high affinity."}, {"t": "Full agonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "A full agonist at Nm that depolarizes the end plate is succinylcholine (and acetylcholine)."}, {"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the curare-like (non-depolarizing) drugs."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine, neostigmine and the other cholinesterase inhibitors (indirect antagonists)."}], "teach": "Varenicline binds the α4β2 neuronal nicotinic (Nn) receptor in the central nervous system with high affinity and activates it only partially. That decreases craving and withdrawal and blunts the effect of nicotine, so it is used for smoking cessation.", "quote": "Varenicline (Chantix) => Selective partial agonist α4β2 NN receptors. MOA: High affinity and Partial Agonist at the α4/β2 central nicotinic (NN) receptor; Decrease craving and withdrawal; Blunt nicotine effect", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 7–8"},
{"id": "DL2-003", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-varenicline", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Where is the site of action of varenicline?", "options": [{"t": "Neuronal nicotinic (Nn) receptors in the brain", "correct": true, "why": "The site of action is the central nervous system, at α4β2 Nn receptors."}, {"t": "Muscle nicotinic (Nm) receptors at the neuromuscular junction", "correct": false, "why": "That is the site of succinylcholine and the curare-like drugs."}, {"t": "M3 receptors in the ciliary muscle of the eye", "correct": false, "why": "That is where echothiophate’s effect is produced."}, {"t": "The presynaptic terminal of motor neurons", "correct": false, "why": "That is the site of botulinum toxin, which prevents acetylcholine release."}], "teach": "Varenicline’s site of action is the central nervous system. Its receptor there is the α4β2 neuronal nicotinic (Nn) receptor; the muscle nicotinic (Nm) receptor at the neuromuscular junction is a different receptor.", "quote": "SOA: CNS", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 8"},
{"id": "DL2-004", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-varenicline", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which adverse effects are reported for varenicline? Select all that apply.", "options": [{"t": "Nausea and vomiting", "correct": true, "why": "Listed as the most common GI side effect (nausea 16–40%)."}, {"t": "Headache", "correct": true, "why": "Listed under central nervous system side effects."}, {"t": "Insomnia", "correct": true, "why": "Listed under central nervous system side effects."}, {"t": "Depression", "correct": true, "why": "Listed under central nervous system side effects."}, {"t": "Hyperkalemia", "correct": false, "why": "Hyperkalemia is a succinylcholine adverse reaction (muscle cells lose K+)."}, {"t": "Histamine release with hypotension", "correct": false, "why": "That is a curare-like drug adverse reaction (most with atracurium)."}], "teach": "Varenicline’s most common side effects are gastrointestinal (nausea and vomiting) and central nervous system effects (headache, insomnia, depression). The drug list also warns of mood and behavioral changes.", "quote": "Side Effects. Most common: GI: Nausea (16-40%) & Vomiting. CNS: Headache, Insomnia, Depression", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 9", "note": "The drug list gives headache, insomnia, suicidal thoughts, depression and flatulence and does not list nausea; the slide lists nausea and vomiting as the most common and does not list suicidal thoughts or flatulence. Keyed to the slide."},
{"id": "DL2-005", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-succinylcholine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of succinylcholine?", "options": [{"t": "Depolarizing agonist at muscle nicotinic (Nm) receptors", "correct": true, "why": "Succinylcholine opens the nicotinic channel and depolarizes the motor end plate: a depolarizing agent."}, {"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the non-depolarizing (curare-like) drugs."}, {"t": "Partial agonist at neuronal nicotinic (Nn) receptors", "correct": false, "why": "That is varenicline."}, {"t": "Organophosphate inhibitor of acetylcholinesterase", "correct": false, "why": "That is echothiophate."}], "teach": "Succinylcholine resembles two acetylcholine molecules joined at the alkyl ends. It is an agonist: it opens the nicotinic channel at the neuromuscular junction, but it is not metabolized effectively at the synapse, so the end plate stays depolarized and the muscle is paralyzed.", "quote": "Depolarize at the NMJ — Depolarizing Agent. Succinylcholine = Open nicotinic ion channels — Agonist", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19–20"},
{"id": "DL2-006", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "phase-succinylcholine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about succinylcholine’s Phase I and Phase II block is CORRECT?", "options": [{"t": "Phase I keeps the end plate depolarized; Phase II blocks the channel", "correct": true, "why": "Phase I: prolonged depolarization (no repolarization). Phase II: channel blockade prevents movement of Na+/K+ and prolongs the paralysis."}, {"t": "Phase I blocks the channel; Phase II keeps the end plate depolarized", "correct": false, "why": "Reverses the two phases."}, {"t": "Both phases are competitive block at the acetylcholine binding site", "correct": false, "why": "Competitive block at the binding site is how curare-like drugs act; succinylcholine is an agonist."}, {"t": "Phase II is produced by inhibition of acetylcholinesterase", "correct": false, "why": "Cholinesterase inhibition is the indirect mechanism of drugs such as neostigmine."}], "teach": "In Phase I succinylcholine opens the channel and, because it is not metabolized effectively at the synapse, keeps the motor end plate depolarized; contraction needs end-plate repolarization (“repriming”), so the muscle is paralyzed. In Phase II the channel is blocked, which prevents movement of Na+ and K+ and prolongs the paralysis.", "quote": "Phase I block (depolarizing): It is an agonist, open the channel, but it cause depolarization of the motor end plate because succinylcholine is not metabolized effectively at the synapse … Phase II block: Channel blockade prevent movement of Na+/K+ and prolongs the paralysis", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 24"},
{"id": "DL2-007", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-succinylcholine", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which adverse drug reactions are listed for succinylcholine? Select all that apply.", "options": [{"t": "Hyperkalemia", "correct": true, "why": "The muscle cell loses K+ (and gains Ca++ and Na+)."}, {"t": "Hypertension and arrhythmias", "correct": true, "why": "Listed as the cardiovascular adverse reactions."}, {"t": "Post-operative muscle pain (myalgia)", "correct": true, "why": "Caused by unsynchronized contractions."}, {"t": "Histamine release with marked hypotension", "correct": false, "why": "That is a curare-like drug reaction (atracurium most)."}, {"t": "Miosis and lacrimation", "correct": false, "why": "Those are echothiophate (eye) reactions."}, {"t": "Insomnia and depression", "correct": false, "why": "Those are varenicline reactions."}], "teach": "Succinylcholine’s adverse reactions are hyperkalemia (muscle cells lose K+), hypertension and arrhythmias, and post-operative muscle pain from unsynchronized contractions. It is avoided in renal-deficient and dehydrated patients.", "quote": "Succinylcholine (SCh) ADRs: Hyperkalemia — Muscle cell loss of K+ & gain of Ca++, & Na+; Cardiovascular — Hypertension & Arrhythmias; Post-operative muscle pain — Myalgia; Unsynchronized contractions", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 25"},
{"id": "DL2-008", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-succinylcholine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Besides the muscle nicotinic (Nm) receptor at the neuromuscular junction, at increased doses succinylcholine can also stimulate which site?", "options": [{"t": "Autonomic ganglia, and thus the PNS and SNS", "correct": true, "why": "At increased doses succinylcholine stimulates ganglia, and thus the parasympathetic (PNS) and sympathetic (SNS) nervous systems."}, {"t": "Muscarinic M3 receptors in the bladder", "correct": false, "why": "M3 in the bladder is the site of the overactive-bladder antagonists (oxybutynin and others)."}, {"t": "The presynaptic terminal, blocking acetylcholine release", "correct": false, "why": "Blocking release at the presynaptic terminal is botulinum toxin."}, {"t": "α4β2 receptors in the brain", "correct": false, "why": "That is varenicline’s site."}], "teach": "Succinylcholine’s main site is the muscle nicotinic (Nm) receptor at the neuromuscular junction. At increased doses it also stimulates the autonomic ganglia, where neuronal nicotinic (Nn) receptors activate the postganglionic neurons of the parasympathetic nervous system (PNS) and sympathetic nervous system (SNS).", "quote": "SCh will stimulate ganglia and thus PNS & SNS — ↑ Doses", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 20"},
{"id": "DL2-009", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "ddi-succinylcholine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "A patient receives succinylcholine together with an inhaled anesthetic such as halothane. Which reaction is this combination associated with?", "options": [{"t": "Malignant hyperthermia", "correct": true, "why": "Listed as the succinylcholine drug–drug interaction with inhaled anesthetics: abnormal Ca++ release from skeletal-muscle stores and muscle heat production."}, {"t": "Histamine release and bronchial spasm", "correct": false, "why": "Histamine release is a curare-like drug reaction (atracurium)."}, {"t": "Hypertensive crisis from dietary tyramine", "correct": false, "why": "That is the phenelzine reaction."}, {"t": "Rebound nasal congestion", "correct": false, "why": "That is the phenylephrine reaction."}], "teach": "With inhaled anesthetics, succinylcholine is associated with malignant hyperthermia: abnormal release of Ca++ from stores in skeletal muscle and heat production by skeletal muscle. Dantrolene is an antagonist at the ryanodine receptor and lowers intracellular Ca++.", "quote": "Succinylcholine (SCh) DDI: Inhaled anesthetics (e.g., halothane) — Malignant hyperthermia. Caused by: Abnormal release of Ca++ from stores in skeletal muscle; Skeletal muscle heat production. Dantrolene — Antagonist to the Ryanodine receptor", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 26", "note": "The drug list places hyperthermia among succinylcholine’s adverse reactions; the slide places malignant hyperthermia under drug–drug interactions with inhaled anesthetics. Keyed to the slide."},
{"id": "DL2-010", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-curare", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of rocuronium?", "options": [{"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": true, "why": "Rocuronium is a curare-like, non-depolarizing agent: it binds the acetylcholine site and stops the channel from opening."}, {"t": "Depolarizing agonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is succinylcholine."}, {"t": "Inhibitor of acetylcholinesterase at the neuromuscular junction", "correct": false, "why": "That is neostigmine and pyridostigmine, which reverse curare-like drugs."}, {"t": "Cleavage of SNARE proteins in the presynaptic terminal", "correct": false, "why": "That is botulinum toxin."}], "teach": "The curare-like (non-depolarizing) drugs — tubocurarine (prototype), mivacurium, vecuronium, rocuronium, pancuronium — are direct competitive antagonists. They bind the acetylcholine binding site on the muscle nicotinic (Nm) receptor without opening it; acetylcholine is needed for muscle contraction, so the muscle is paralyzed.", "quote": "Non-depolarizing = Stop the nicotinic ion channels from opening — Competitive Antagonist (Curare (prototype), Mivacurium, Vecuronium, Rocuronium, Pancuronium)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19, 27"},
{"id": "DL2-011", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-nondepolarizing", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs are non-depolarizing neuromuscular blocking agents? Select all that apply.", "options": [{"t": "Vecuronium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Rocuronium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Pancuronium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Mivacurium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Succinylcholine", "correct": false, "why": "Succinylcholine is the depolarizing agent (an agonist)."}, {"t": "Neostigmine", "correct": false, "why": "Neostigmine is a cholinesterase inhibitor; it reverses curare-like drugs."}, {"t": "Edrophonium", "correct": false, "why": "Edrophonium is a short-acting cholinesterase inhibitor."}], "teach": "Both drug types cause paralysis. Depolarizing: succinylcholine (agonist, opens nicotinic channels). Non-depolarizing: curare (prototype), mivacurium, vecuronium, rocuronium and pancuronium (competitive antagonists, stop the nicotinic channels from opening).", "quote": "Depolarizing: Succinylcholine. Non-depolarizing: Curare (prototype), Mivacurium, Vecuronium, Rocuronium, Pancuronium", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19"},
{"id": "DL2-012", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-curare", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which adverse drug reactions are listed for the curare-like (non-depolarizing) drugs? Select all that apply.", "options": [{"t": "Respiratory paralysis", "correct": true, "why": "Listed first among the curare-like drug adverse reactions."}, {"t": "Tachycardia (pancuronium)", "correct": true, "why": "Listed, with pancuronium as the example."}, {"t": "Histamine release with bronchial spasm and hypotension", "correct": true, "why": "Listed as an allergic reaction (atracurium most)."}, {"t": "Sedation and drowsiness from central action", "correct": false, "why": "The curare-like drugs have no CNS effect."}, {"t": "Hyperkalemia from loss of muscle K+", "correct": false, "why": "That is succinylcholine."}], "teach": "Curare-like drugs cause respiratory paralysis, tachycardia (pancuronium) and allergic reactions with histamine release (bronchial spasms, marked hypotension; atracurium most). They have no central nervous system (CNS) effect.", "quote": "Curare Like-Drugs ADRs: Respiratory paralysis; Tachycardia — Pancuronium; Allergic reactions — Histamine release - Bronchial spasms - Marked Hypotension — Atracurium. *** No CNS Effect", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 30, 32", "note": "The drug list gives histamine release, hypotension and tachycardia and omits respiratory paralysis; the slide lists respiratory paralysis first, ties tachycardia to pancuronium and histamine release mainly to atracurium (not on the list). Keyed to the slide."},
{"id": "DL2-013", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "cns-curare", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about the curare-like drugs (for example vecuronium) is CORRECT?", "options": [{"t": "They have no central nervous system effect", "correct": true, "why": "The curare-like drugs have no central nervous system effect."}, {"t": "They cross the blood–brain barrier and cause sedation", "correct": false, "why": "They have no central nervous system effect."}, {"t": "They are agonists that keep the end plate depolarized", "correct": false, "why": "That is succinylcholine."}, {"t": "They raise acetylcholine levels at the synapse", "correct": false, "why": "That is the cholinesterase inhibitors."}], "teach": "The curare-like drugs act only at the neuromuscular junction, where they block the muscle nicotinic (Nm) receptor competitively. They have no central nervous system effect, so a paralyzed patient is not sedated by them; they are used as an adjuvant in surgical anesthesia, not as an anesthetic.", "quote": "*** No CNS Effect. Used as an adjuvant in surgical anesthesia to obtain relaxation of skeletal muscle (Not as anesthetic)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 27, 32"},
{"id": "DL2-014", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "physostigmine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about physostigmine is CORRECT?", "options": [{"t": "It crosses the blood–brain barrier", "correct": true, "why": "Physostigmine is a tertiary amine and readily penetrates the central nervous system."}, {"t": "It is a quaternary amine that stays out of the brain", "correct": false, "why": "That describes pyridostigmine and neostigmine."}, {"t": "It irreversibly phosphorylates acetylcholinesterase", "correct": false, "why": "That is the organophosphates (echothiophate, parathion, sarin)."}, {"t": "It is a muscarinic receptor antagonist", "correct": false, "why": "Physostigmine inhibits acetylcholinesterase; atropine is the muscarinic antagonist."}], "teach": "Physostigmine is a reversible acetylcholinesterase inhibitor with a longer duration of action. As a tertiary amine it readily penetrates the central nervous system, so it acts in the brain and the periphery, and it is the drug of choice for poisoning by anti-muscarinic agents such as atropine.", "quote": "Physostigmine (Antilirium): Tertiary amine and readily Penetrate the CNS. Drug of choice for treating poisoning due to anti-muscarinic agents (e.g., atropine)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39"},
{"id": "DL2-015", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "physostigmine-use", "tags": ["drug-list", "use"], "source": "slide", "fg": "classes", "stem": "A patient is poisoned with atropine. Which cholinesterase inhibitor is the drug of choice?", "options": [{"t": "Physostigmine", "correct": true, "why": "Drug of choice for poisoning by anti-muscarinic agents such as atropine; it reaches the central nervous system."}, {"t": "Neostigmine", "correct": false, "why": "Neostigmine does not cross the blood–brain barrier; its uses are myasthenia gravis and curare reversal."}, {"t": "Edrophonium", "correct": false, "why": "Edrophonium is short-acting and used to diagnose myasthenia gravis."}, {"t": "Echothiophate", "correct": false, "why": "Echothiophate is an organophosphate used in the eye for glaucoma."}], "teach": "Atropine blocks muscarinic receptors in the brain and periphery. Physostigmine raises acetylcholine by inhibiting acetylcholinesterase and, as a tertiary amine, reaches the central nervous system too, so it is the drug of choice for anti-muscarinic poisoning.", "quote": "Drug of choice for treating poisoning due to anti-muscarinic agents (e.g., atropine)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39"},
{"id": "DL2-016", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "bbb-ache", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which acetylcholinesterase inhibitors cross the blood–brain barrier? Select all that apply.", "options": [{"t": "Physostigmine", "correct": true, "why": "Tertiary amine; readily penetrates the central nervous system."}, {"t": "Donepezil", "correct": true, "why": "Lipophilic; crosses the blood–brain barrier (Alzheimer’s disease)."}, {"t": "Rivastigmine", "correct": true, "why": "Lipophilic; crosses the blood–brain barrier (Alzheimer’s disease)."}, {"t": "Galantamine", "correct": true, "why": "Lipophilic; crosses the blood–brain barrier (Alzheimer’s disease)."}, {"t": "Neostigmine", "correct": false, "why": "Quaternary amine; does NOT cross the blood–brain barrier."}, {"t": "Pyridostigmine", "correct": false, "why": "Quaternary amine; does NOT cross the blood–brain barrier."}], "teach": "Physostigmine (tertiary amine) and the Alzheimer’s drugs donepezil, rivastigmine and galantamine (lipophilic) cross the blood–brain barrier. Pyridostigmine and neostigmine are quaternary amines and do not, so they act at the neuromuscular junction without central effects.", "quote": "Physostigmine: Tertiary amine and readily Penetrate the CNS. PyriDOstigmine & Neostigmine: Quaternary amine and DO NOT cross the BBB. Donepezil, Rivastigmine and Galantamine: Lipophilic (Cross the BBB)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1–2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39–40"},
{"id": "DL2-017", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "neostigmine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about neostigmine and pyridostigmine is CORRECT?", "options": [{"t": "They do not cross the blood–brain barrier", "correct": true, "why": "They are quaternary amines and do NOT cross the blood–brain barrier, so their site of action is the neuromuscular junction."}, {"t": "They are the drugs of choice for atropine poisoning", "correct": false, "why": "That is physostigmine, which reaches the brain."}, {"t": "They are used for early Alzheimer’s disease", "correct": false, "why": "That is donepezil, rivastigmine and galantamine."}, {"t": "They block the muscle nicotinic receptor directly", "correct": false, "why": "They inhibit acetylcholinesterase (indirect); direct block of Nm is the curare-like drugs."}], "teach": "Pyridostigmine and neostigmine are reversible acetylcholinesterase inhibitors with a longer duration of action. They are quaternary amines that do not cross the blood–brain barrier, so they act at the neuromuscular junction: they treat myasthenia gravis and reverse curare-like overdose.", "quote": "PyriDOstigmine (Mestinon) & Neostigmine (Prostigmin): Quaternary amine and DO NOT cross the BBB. Uses: Treatment of myasthenia gravis & to reverse curare-like overdose", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39"},
{"id": "DL2-018", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "reverse-curare", "tags": ["drug-list", "use"], "source": "slide", "fg": "classes", "stem": "A patient remains paralyzed after a curare-like drug. Which drug reverses the block by raising acetylcholine at the neuromuscular junction?", "options": [{"t": "Neostigmine", "correct": true, "why": "A cholinesterase inhibitor used to reverse curare-like overdose; more acetylcholine competes the curare-like drug off the receptor."}, {"t": "Succinylcholine", "correct": false, "why": "Succinylcholine is itself a paralyzing (depolarizing) drug."}, {"t": "Atropine", "correct": false, "why": "Atropine blocks muscarinic receptors; it does not raise acetylcholine."}, {"t": "Botulinum toxin", "correct": false, "why": "Botulinum toxin lowers acetylcholine release and relaxes muscle."}], "teach": "Curare-like drugs are competitive antagonists, so their block can be overcome by more acetylcholine. Neostigmine and pyridostigmine inhibit acetylcholinesterase, raise synaptic acetylcholine at the neuromuscular junction and reverse the block.", "quote": "Cholinesterase Inhibitors … Used to potentiate the actions of Ach … Reverse curare effects. PyriDOstigmine & Neostigmine … to reverse curare-like overdose", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 33, 39"},
{"id": "DL2-019", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "edrophonium", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about edrophonium is CORRECT?", "options": [{"t": "It has a short duration of action", "correct": true, "why": "Edrophonium is short-acting and readily reversible; it is used to diagnose myasthenia gravis."}, {"t": "It irreversibly inhibits acetylcholinesterase", "correct": false, "why": "Irreversible inhibition is the organophosphates."}, {"t": "It is the drug of choice for Alzheimer’s disease", "correct": false, "why": "That is donepezil, rivastigmine and galantamine."}, {"t": "It blocks M3 receptors in the eye", "correct": false, "why": "Blocking M3 in the eye is tropicamide."}], "teach": "Edrophonium is a cholinesterase inhibitor with a short duration of action that is readily reversible. It is used in the diagnosis of myasthenia gravis or when the medication dose needs adjusting (Tensilon test: transient increase in grip strength).", "quote": "Edrophonium (Enlon, Reversol): Short duration of action; Readily reversible; Use in the diagnosis of myasthenia gravis or if the medication need to be adjusted", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 38"},
{"id": "DL2-020", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-ache", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which effect is expected from excess acetylcholine after a cholinesterase inhibitor such as donepezil?", "options": [{"t": "Diarrhea and salivation", "correct": true, "why": "Cholinesterase inhibitor adverse reactions are DUMBBELSS (diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation) from excess acetylcholine."}, {"t": "Dry mouth and constipation", "correct": false, "why": "Those are anti-DUMBBELSS effects of muscarinic antagonists."}, {"t": "Mydriasis", "correct": false, "why": "Mydriasis is an anti-DUMBBELSS effect; excess acetylcholine causes miosis."}, {"t": "Tachycardia and bronchial dilation", "correct": false, "why": "Those are atropine effects; excess acetylcholine causes bradycardia and bronchial constriction."}], "teach": "Cholinesterase inhibitors raise synaptic acetylcholine, so their adverse reactions are the symptoms of excess acetylcholine: DUMBBELSS — diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation. Central effects include insomnia, agitation and dizziness.", "quote": "ADRs: Symptoms due to excess of Ach at synapses — DUMBBELSS; GI (>10%); CNS (>10%) Insomnia & agitation, Dizziness", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 41"},
{"id": "DL2-021", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-echothiophate", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of echothiophate?", "options": [{"t": "Irreversible inhibitor of acetylcholinesterase", "correct": true, "why": "Echothiophate is an organophosphate inhibitor of acetylcholinesterase; organophosphates bind the enzyme covalently (irreversible)."}, {"t": "Reversible, short-acting inhibitor of acetylcholinesterase", "correct": false, "why": "That is edrophonium."}, {"t": "Non-selective muscarinic agonist", "correct": false, "why": "That is pilocarpine and carbachol, which act at the receptor directly."}, {"t": "Muscarinic antagonist in the eye", "correct": false, "why": "That is tropicamide, which dilates the pupil."}], "teach": "Echothiophate is an organophosphate: it inhibits acetylcholinesterase and raises acetylcholine, which increases M3 activation in the ciliary muscle and lowers intraocular pressure by increasing aqueous humor outflow (glaucoma). Organophosphates form a stable covalent bond with the enzyme, so the inhibition is irreversible.", "quote": "Echothiophate (Phospholine) MOA: Organophosphate inhibitor of the acetylcholinesterase enzyme & ↑ Ach levels. Organophosphates: Forms a covalent bond with the enzyme that is very stable and slow (Irreversible)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 42, 45", "note": "The drug list does not say whether echothiophate is reversible; the slides call organophosphates irreversible. Keyed to the slides."},
{"id": "DL2-022", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-adr-echothiophate", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Echothiophate acts through M3 receptors in the ciliary muscle of the eye. Which adverse reactions does it cause? Select all that apply.", "options": [{"t": "Miosis and blurred vision", "correct": true, "why": "Listed adverse reaction: more M3 activation constricts the pupil."}, {"t": "Lacrimation", "correct": true, "why": "Listed adverse reaction."}, {"t": "Stinging and redness of the eyes", "correct": true, "why": "Listed adverse reaction."}, {"t": "Mydriasis", "correct": false, "why": "Mydriasis is what tropicamide (an M3 antagonist) produces."}, {"t": "Dry eyes", "correct": false, "why": "Raised acetylcholine increases lacrimation, not dryness."}], "teach": "Echothiophate raises acetylcholine and so increases M3 activation in the ciliary muscle (its site of action). Its listed adverse reactions are miosis and blurred vision, lacrimation, and stinging and redness of the eyes.", "quote": "ADR: Miosis and blurred vision; Lacrimation; Stinging and redness of the eyes", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 45"},
{"id": "DL2-023", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "botox", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of botulinum toxin?", "options": [{"t": "Blocks acetylcholine release by cleaving SNARE", "correct": true, "why": "Botulinum toxin is an endopeptidase; it cleaves sites on SNARE proteins in the presynaptic terminal, so acetylcholine cannot be released."}, {"t": "Competitively blocks muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the curare-like drugs, which act on the postsynaptic receptor."}, {"t": "Inhibits acetylcholinesterase in the synaptic cleft", "correct": false, "why": "That is the cholinesterase inhibitors, which raise acetylcholine."}, {"t": "Depolarizes the motor end plate", "correct": false, "why": "That is succinylcholine."}], "teach": "Botulinum toxin acts at the presynaptic terminal. Its active fragments are endopeptidases whose substrates are the SNARE proteins needed for vesicle docking and exocytosis; cleaving them blocks acetylcholine release, which relaxes muscle.", "quote": "Botulinum toxin blocks ACh release by interfering with the machinery of transmitter release. The active fragments of botulinum toxins are endopeptidases; the SNARE proteins are their substrates. The botulinum toxin cleaves specific sites on SNARE proteins. By ↓ Ach release => Muscle relaxation", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 46, 50", "note": "The drug list colours botulinum toxin red (antagonist); the slides describe it as blocking acetylcholine release, not as a receptor antagonist. Keyed to the slide wording."},
{"id": "DL2-024", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-indirect-nmj", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs act as indirect antagonists by inhibiting acetylcholinesterase? Select all that apply.", "options": [{"t": "Physostigmine", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Pyridostigmine", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Edrophonium", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Rivastigmine", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Succinylcholine", "correct": false, "why": "A direct depolarizing agonist at Nm."}, {"t": "Varenicline", "correct": false, "why": "A direct partial agonist at α4β2 Nn."}, {"t": "Botulinum toxin", "correct": false, "why": "Prevents acetylcholine release; it does not inhibit acetylcholinesterase."}], "teach": "Indirect drugs at the neuromuscular junction bind the enzyme that breaks down acetylcholine, not the receptor: acetylcholinesterase antagonists such as physostigmine, pyridostigmine, neostigmine, edrophonium, donepezil, rivastigmine, galantamine and echothiophate. Blocking the enzyme raises synaptic acetylcholine.", "quote": "Indirect Antagonist: Acetylcholinesterase enzyme antagonist — Blocks the breakdown of Ach, which ↑ Ach synaptic levels", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1–2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 10, 12"},
{"id": "DL2-025", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-agonist-nmj", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs in the neuromuscular section of the drug list are direct nicotinic agonists? Select all that apply.", "options": [{"t": "Acetylcholine", "correct": true, "why": "Endogenous agonist; a depolarizing agent at Nm."}, {"t": "Succinylcholine", "correct": true, "why": "Depolarizing agonist at Nm."}, {"t": "Varenicline", "correct": true, "why": "Partial agonist at α4β2 neuronal nicotinic (Nn) receptors."}, {"t": "Rocuronium", "correct": false, "why": "A competitive antagonist (non-depolarizing)."}, {"t": "Neostigmine", "correct": false, "why": "An acetylcholinesterase inhibitor (indirect)."}, {"t": "Botulinum toxin", "correct": false, "why": "Prevents acetylcholine release."}], "teach": "The nicotinic agonists are acetylcholine, nicotine, varenicline (selective partial agonist at α4β2 Nn) and succinylcholine. Curare-like drugs are direct antagonists; cholinesterase inhibitors are indirect.", "quote": "Nicotinic NN PCOL: Agonists — Ach; Nicotine; Varenicline (Chantix) => Selective partial agonist α4β2 NN receptors; Succinylcholine", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 7"},
{"id": "DL2-026", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-bethanechol", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of bethanechol?", "options": [{"t": "Non-selective, reversible muscarinic (M1–M3) agonist", "correct": true, "why": "Bethanechol is grouped with acetylcholine, methacholine and carbachol as a non-selective muscarinic agonist."}, {"t": "Non-selective, reversible muscarinic (M1–M3) antagonist", "correct": false, "why": "That is atropine."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine and neostigmine (indirect)."}, {"t": "Partial agonist at neuronal nicotinic (Nn) receptors", "correct": false, "why": "That is varenicline."}], "teach": "Acetylcholine, methacholine, carbachol, bethanechol, pilocarpine and cevimeline are non-selective, reversible agonists at the muscarinic receptors (M1, M2, M3). They differ in hydrolysis by acetylcholinesterase and in which organs respond most.", "quote": "Muscarinic Agonist MOA: Non-selective agonist for the muscarinic receptors (M1-3); Reversible", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-Cholinergic-26s.pdf slide 11–12"},
{"id": "DL2-027", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "group-musc-agonists", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs are non-selective muscarinic agonists? Select all that apply.", "options": [{"t": "Methacholine", "correct": true, "why": "Non-selective muscarinic agonist (M1–M3)."}, {"t": "Carbachol", "correct": true, "why": "Non-selective muscarinic agonist (M1–M3)."}, {"t": "Pilocarpine", "correct": true, "why": "Non-selective muscarinic agonist (M1–M3)."}, {"t": "Cevimeline", "correct": true, "why": "Non-selective muscarinic agonist (M1–M3)."}, {"t": "Scopolamine", "correct": false, "why": "A muscarinic antagonist."}, {"t": "Tiotropium", "correct": false, "why": "A muscarinic (M1 and M3) antagonist."}, {"t": "Physostigmine", "correct": false, "why": "An acetylcholinesterase inhibitor; it raises acetylcholine but does not bind the receptor."}], "teach": "The direct muscarinic agonists are acetylcholine, methacholine, carbachol, bethanechol, pilocarpine and cevimeline; all are non-selective (M1, M2, M3) and reversible. Physostigmine reaches the same receptors indirectly by raising acetylcholine.", "quote": "Muscarinic Agonist: Acetylcholine, Methacholine, Carbachol, Bethanechol, Pilocarpine & Cevimeline — Non-selective (M1, M2, & M3s), Reversible", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2–3; PCOL-Cholinergic-26s.pdf slide 11"},
{"id": "DL2-028", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "hydrolysis-agonists", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which muscarinic agonists are NOT hydrolyzed by acetylcholinesterase? Select all that apply.", "options": [{"t": "Carbachol", "correct": true, "why": "Hydrolysis by acetylcholinesterase: carbachol − (none)."}, {"t": "Pilocarpine", "correct": true, "why": "Hydrolysis by acetylcholinesterase: pilocarpine − (none); it is a non-ester alkaloid."}, {"t": "Acetylcholine", "correct": false, "why": "Acetylcholine is hydrolyzed the most (+++)."}, {"t": "Methacholine", "correct": false, "why": "Methacholine is hydrolyzed a little (+)."}], "teach": "In the muscarinic agonist table, hydrolysis by acetylcholinesterase is +++ for acetylcholine, + for methacholine and absent (−) for carbachol and pilocarpine. Pilocarpine is an alkaloid, a non-ester, and is not hydrolyzed.", "quote": "Agonist / Hydrolysis by AchE: Ach +++; Methacholine +; Carbachol -; Pilocarpine -", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-Cholinergic-26s.pdf slide 12"},
{"id": "DL2-029", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "pilocarpine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about pilocarpine is CORRECT?", "options": [{"t": "It has no effect on nicotinic receptors", "correct": true, "why": "Pilocarpine is a non-ester alkaloid, not hydrolyzed, with no effect on nicotinic receptors."}, {"t": "It is rapidly hydrolyzed by acetylcholinesterase", "correct": false, "why": "Pilocarpine is a non-ester and is not hydrolyzed."}, {"t": "It is selective for the M2 receptor", "correct": false, "why": "It is a non-selective muscarinic agonist (M1, M2, M3)."}, {"t": "It blocks muscarinic receptors and dries the mouth", "correct": false, "why": "It activates muscarinic receptors; it is used to treat dry mouth."}], "teach": "Pilocarpine is a non-selective, reversible muscarinic agonist. As an alkaloid it is a non-ester, is not hydrolyzed and has no effect on nicotinic receptors. It is used topically for glaucoma and to treat dry mouth (M3 on salivary glands → salivation).", "quote": "Pilocarpine (Alkaloids): Non-Ester and not hydrolyzed; No effect on Nicotinic receptors; Used topically to treat glaucoma and to treat dry mouth", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 14"},
{"id": "DL2-030", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-musc-agonist", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "A patient takes bethanechol. Which effect is NOT expected?", "options": [{"t": "Mydriasis", "correct": true, "why": "Muscarinic agonists cause miosis (M3 in the iris); mydriasis is an antagonist effect."}, {"t": "Diarrhea", "correct": false, "why": "Expected: M3 in the gut increases peristalsis and secretion (the D of DUMBBELSS)."}, {"t": "Bradycardia", "correct": false, "why": "Expected: M2 in the heart lowers heart rate."}, {"t": "Bronchial constriction", "correct": false, "why": "Expected: M3 on bronchial smooth muscle."}, {"t": "Salivation", "correct": false, "why": "Expected: M3 on glands."}], "teach": "Muscarinic agonists produce DUMBBELSS: diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation of the central nervous system. Bradycardia comes through M2 in the heart (Gi); the rest of the peripheral effects come through M3 (Gq, ↑Ca++).", "quote": "Autonomic Effects Evoked by Muscarinic Agonists: GI tract — Increase peristalsis & Secretion; Urinary Bladder — Micturation; Eye (Iris) — Miosis; Heart — Bradycardia; Lungs — Bronchial constriction; CNS — Vomiting; Glands — Secretion (Salivation & lacrimation)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-Cholinergic-26s.pdf slide 13"},
{"id": "DL2-031", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-atropine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of atropine?", "options": [{"t": "Non-selective muscarinic (M1–M3) antagonist", "correct": true, "why": "Atropine is a naturally occurring alkaloid that blocks M1, M2 and M3, reversibly."}, {"t": "Non-selective muscarinic (M1–M3) agonist", "correct": false, "why": "That is bethanechol, carbachol and the other muscarinic agonists."}, {"t": "Selective M1 and M3 muscarinic antagonist", "correct": false, "why": "That is tiotropium."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine, which treats atropine poisoning."}], "teach": "Atropine is a non-selective, reversible muscarinic antagonist (M1, M2, M3), acting in the central nervous system and periphery. Blocking the receptors where acetylcholine produces DUMBBELSS gives the anti-DUMBBELSS picture.", "quote": "Muscarinic Antagonists: Naturally occurring Alkaloids; Non-selective and reversible; Atropine (M1, M2, and M3)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 17"},
{"id": "DL2-032", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-atropine", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which effects are expected from an overdose of atropine? Select all that apply.", "options": [{"t": "Tachycardia", "correct": true, "why": "M2 block in the heart → ↑ heart rate."}, {"t": "Mydriasis", "correct": true, "why": "M3 block in the pupil → mydriasis."}, {"t": "Constipation", "correct": true, "why": "M3 block in the gastrointestinal tract → constipation."}, {"t": "Dry mouth", "correct": true, "why": "M3 block on glands → dry mouth."}, {"t": "Bronchial constriction", "correct": false, "why": "Atropine causes bronchial dilation; constriction is a muscarinic agonist effect."}, {"t": "Miosis", "correct": false, "why": "Miosis is a muscarinic agonist effect; atropine dilates the pupil."}, {"t": "Salivation", "correct": false, "why": "Salivation is a muscarinic agonist effect."}], "teach": "Atropine overdose gives anti-DUMBBELSS: M2 block in the heart raises heart rate; M3 block causes mydriasis, constipation, dry mouth and bronchial dilation. Toxicity is summarized as dry as a bone, hot as a pistol, red as a beet, blind as a bat, mad as a hatter.", "quote": "Atropine OD of Muscarinic Antagonist — Anti-DUMBBELSS: M2 Heart = Gi = ↑ HR; M3 Pupil = Gq = Mydriasis; M3 GI = Gq = Constipation. Pharmacological effects: Dry mouth & constipation; Tachycardia; Bronchial dilation; Pupil dilation", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 19, 32", "note": "The drug list also gives drowsiness for atropine; the slides give its central effects as hallucinations, restlessness and coma (dose-dependent) and give drowsiness for scopolamine. Drowsiness is not keyed here."},
{"id": "DL2-033", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "atropine-heart", "tags": ["drug-list", "apply"], "source": "slide", "fg": "classes", "stem": "Atropine raises heart rate by blocking which receptor?", "options": [{"t": "M2 in the heart", "correct": true, "why": "M2 (Gi) at the SA and AV node lowers heart rate when acetylcholine binds; blocking it raises heart rate."}, {"t": "M3 in the heart", "correct": false, "why": "M3 mediates smooth muscle, gland, eye and endothelial effects; the cardiac muscarinic receptor is M2."}, {"t": "β1 in the heart", "correct": false, "why": "β1 is the adrenergic receptor that raises heart rate when activated; atropine does not act there."}, {"t": "Neuronal nicotinic (Nn) in ganglia", "correct": false, "why": "Atropine is a muscarinic antagonist, not a nicotinic one."}], "teach": "Acetylcholine slows the heart through M2 (Gi, ↓cAMP) at the SA and AV node. Atropine blocks M2, so the parasympathetic brake is removed and heart rate rises; atropine is used for bradycardia or atrioventricular nodal block.", "quote": "Location? M2 Heart = Gi = ↑ HR. M2: AV & SA node", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 10, 19"},
{"id": "DL2-034", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "atropine-organophosphate", "tags": ["drug-list", "use"], "source": "slide", "fg": "classes", "stem": "In organophosphate poisoning, how does atropine help?", "options": [{"t": "It blocks excess acetylcholine at muscarinic sites", "correct": true, "why": "Atropine (M1, M2, M3 antagonist) reduces the effects of acetylcholine at muscarinic sites: anti-DUMBBELSS."}, {"t": "It regenerates the phosphorylated acetylcholinesterase", "correct": false, "why": "Regenerating the enzyme is pralidoxime (2-PAM), the cholinesterase reactivator."}, {"t": "It lowers acetylcholine release from the nerve terminal", "correct": false, "why": "That is botulinum toxin."}, {"t": "It blocks nicotinic receptors at the neuromuscular junction", "correct": false, "why": "Atropine acts at muscarinic, not nicotinic, receptors."}], "teach": "Organophosphates irreversibly inhibit acetylcholinesterase, so acetylcholine builds up and produces severe DUMBBELSS. Atropine blocks M1, M2 and M3 and reduces the effects of acetylcholine at muscarinic sites; pralidoxime (2-PAM) reactivates the enzyme.", "quote": "Antidote for Overdose of Organophosphate AchE inhibitor: Atropine — M1, M2, & M3 Antag — Anti-DUMBBELSS. Atropine Uses: Treatment of Muscarinic Agonist overdose; Bradycardia or atrioventricular nodal block; Organophosphates Poisoning", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 44; PCOL-Cholinergic-26s.pdf slide 20"},
{"id": "DL2-035", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-scopolamine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of scopolamine?", "options": [{"t": "Muscarinic, histamine and serotonin antagonist", "correct": true, "why": "Scopolamine is a non-selective, reversible alkaloid antagonist at muscarinic, histamine and serotonin receptors."}, {"t": "Selective antagonist at M3 receptors in the bladder", "correct": false, "why": "That is solifenacin, darifenacin and trospium."}, {"t": "Non-selective muscarinic (M1–M3) agonist", "correct": false, "why": "That is pilocarpine and the other agonists."}, {"t": "Inhibitor of acetylcholinesterase in the brain", "correct": false, "why": "That is donepezil and the other lipophilic cholinesterase inhibitors."}], "teach": "Scopolamine, like atropine, is a naturally occurring, non-selective and reversible muscarinic antagonist; it also antagonizes histamine and serotonin receptors. It penetrates the central nervous system more rapidly than atropine and is used for motion sickness.", "quote": "Scopolamine — Antagonist to the Muscarinic, Histamine and serotonin receptors", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 17", "note": "The drug list calls scopolamine a non-selective muscarinic antagonist (M1, M2, M3) and does not mention histamine or serotonin receptors; the slide does. Keyed to the slide."},
{"id": "DL2-036", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "scopolamine-cns", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about scopolamine is CORRECT?", "options": [{"t": "It penetrates the CNS more rapidly", "correct": true, "why": "Scopolamine penetrates the central nervous system (CNS) more rapidly; its effects include drowsiness, euphoria and amnesia, and it is used for motion sickness."}, {"t": "It does not cross into the CNS", "correct": false, "why": "Not crossing the blood–brain barrier describes neostigmine and pyridostigmine."}, {"t": "It is used to dilate the pupil for eye exams", "correct": false, "why": "That is tropicamide."}, {"t": "It is a short-acting inhaled bronchodilator", "correct": false, "why": "That is ipratropium."}], "teach": "Scopolamine is a muscarinic antagonist whose site of action is mainly the central nervous system (CNS), which it penetrates more rapidly. It causes drowsiness, euphoria and amnesia, and produces anti-DUMBBELSS effects; it is used for motion sickness.", "quote": "Scopolamine: Penetrates the CNS more rapidly; Motion sickness; Drowsiness, euphoria, amnesia; Anti-DUMBBELSS", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 24"},
{"id": "DL2-037", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "benztropine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Benztropine is a muscarinic antagonist. Where is its site of action?", "options": [{"t": "The central nervous system", "correct": true, "why": "Benztropine is used in Parkinson’s patients for tremor and rigidity; it acts in the central nervous system."}, {"t": "The lungs, by inhalation", "correct": false, "why": "That is ipratropium, tiotropium, aclidinium and umeclidinium."}, {"t": "M3 receptors in the bladder", "correct": false, "why": "That is the overactive-bladder antagonists."}, {"t": "The eye (pupil)", "correct": false, "why": "That is tropicamide."}], "teach": "In Parkinson’s disease, 70–80% of the dopaminergic neurons from the substantia nigra to the striatum are lost and acetylcholine activity is left unopposed. Benztropine blocks muscarinic receptors in the central nervous system and is used for tremor and rigidity in Parkinson’s patients treated with L-dopa.", "quote": "Benztropine (Cogentin): Parkinson’s Pts treated with L-Dopa; Tremor & rigidity; Basal Ganglia; Dopaminergic Neuron 70-80% loss", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 25"},
{"id": "DL2-038", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "tropicamide", "tags": ["drug-list", "apply"], "source": "slide", "fg": "classes", "stem": "Tropicamide dilates the pupil. Which mechanism explains this?", "options": [{"t": "It blocks M3, leaving the SNS unopposed", "correct": true, "why": "The parasympathetic system constricts the pupil through M3 (Gq → IP3, Ca++); blocking M3 leaves the sympathetic nervous system (SNS) unopposed → mydriasis."}, {"t": "It activates α1 receptors on the radial muscle", "correct": false, "why": "Activating α1 to cause mydriasis is phenylephrine."}, {"t": "It inhibits acetylcholinesterase in the eye", "correct": false, "why": "Inhibiting acetylcholinesterase in the eye (echothiophate) causes miosis."}, {"t": "It activates M3 receptors in the ciliary muscle", "correct": false, "why": "M3 activation constricts the pupil (miosis)."}], "teach": "The sympathetic nervous system (SNS) dilates the pupil and the parasympathetic nervous system (PNS) constricts it through M3 (Gq → PLC → IP3 and Ca++). Tropicamide blocks M3 in the eye, so the SNS is unopposed and the pupil dilates (mydriasis).", "quote": "Tropicamide — Use: Optical (Pupil Dilation). Rational? SNS dilate the pupils; PNS constrict the pupils — M3 => Gq => PLC => IP3 & Ca++ = Pupil Constriction (miosis). SNS is unopposed => Mydriasis", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 26"},
{"id": "DL2-039", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "ipra-vs-tio", "tags": ["drug-list", "tell"], "source": "slide", "fg": "classes", "stem": "Which statement correctly tells ipratropium and tiotropium apart?", "options": [{"t": "Ipratropium blocks M1, M2 and M3; tiotropium blocks M1 and M3", "correct": true, "why": "Ipratropium: M1, M2 and M3, short acting (SAMA, 3–4 times a day). Tiotropium: M1 and M3, long acting (LAMA, once a day)."}, {"t": "Ipratropium blocks M1 and M3; tiotropium blocks M1, M2 and M3", "correct": false, "why": "Reverses the two receptor profiles."}, {"t": "Both are agonists at M3 in bronchial smooth muscle", "correct": false, "why": "Both are antagonists; M3 activation constricts the bronchi."}, {"t": "Ipratropium is long acting; tiotropium is short acting", "correct": false, "why": "Reversed: ipratropium is the short-acting muscarinic antagonist (SAMA), tiotropium the long-acting one (LAMA)."}], "teach": "Both are inhaled muscarinic antagonists used in the lungs, where M3 (Gq → IP3, Ca++) constricts bronchial smooth muscle and only the parasympathetic system innervates. Ipratropium (M1, M2, M3) is a short-acting muscarinic antagonist (SAMA); tiotropium (M1 and M3) is a long-acting muscarinic antagonist (LAMA).", "quote": "Ipratropium (Atrovent): M1, M2, and M3; SAMA: Short acting (3-4x/Day). Tiotropium (Spiriva): M1 and M3; LAMA: Long acting (1x/Day)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 28"},
{"id": "DL2-040", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-tiotropium", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which inhaled muscarinic antagonist blocks M1 and M3 but not M2?", "options": [{"t": "Tiotropium", "correct": true, "why": "Tiotropium: M1 and M3; long-acting muscarinic antagonist (LAMA)."}, {"t": "Ipratropium", "correct": false, "why": "Ipratropium blocks M1, M2 and M3."}, {"t": "Atropine", "correct": false, "why": "Atropine blocks M1, M2 and M3 and is not the inhaled agent."}, {"t": "Scopolamine", "correct": false, "why": "Scopolamine is a non-selective antagonist acting mainly in the central nervous system."}], "teach": "Tiotropium blocks M1 and M3 and is long acting (once a day). Because M2 sits at the SA and AV node, the drug list notes that tiotropium does not affect heart rate.", "quote": "Tiotropium (Spiriva): M1 and M3; LAMA: Long acting (1x/Day)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 28"},
{"id": "DL2-041", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "aclidinium", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about aclidinium and umeclidinium is CORRECT?", "options": [{"t": "They have high affinity for M3 and dissociate slowly", "correct": true, "why": "They have high affinity for M3; binding is reversible, but dissociation is slow. Site of action: the lungs."}, {"t": "They are irreversible M3 antagonists", "correct": false, "why": "They are reversible, with slow dissociation."}, {"t": "They are muscarinic agonists for dry mouth", "correct": false, "why": "Agonists for dry mouth are pilocarpine and cevimeline."}, {"t": "They act on M3 in the bladder for overactive bladder", "correct": false, "why": "That is oxybutynin and the other overactive-bladder drugs."}], "teach": "Aclidinium and umeclidinium are inhaled muscarinic antagonists acting in the lungs. They bind M3 with high affinity; the binding is reversible, but they dissociate slowly. The drug list classes them as long-acting muscarinic antagonists.", "quote": "Aclidinium and Umeclidinium: High affinity for the M3 (reversible, but slow dissociation)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 28"},
{"id": "DL2-042", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "soa-lungs", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which muscarinic antagonists have the lungs as their site of action? Select all that apply.", "options": [{"t": "Ipratropium", "correct": true, "why": "Inhaled; short-acting muscarinic antagonist."}, {"t": "Tiotropium", "correct": true, "why": "Inhaled; long-acting muscarinic antagonist."}, {"t": "Umeclidinium", "correct": true, "why": "Inhaled; high M3 affinity."}, {"t": "Oxybutynin", "correct": false, "why": "Site of action: M3 in the bladder."}, {"t": "Tropicamide", "correct": false, "why": "Site of action: the eye."}, {"t": "Benztropine", "correct": false, "why": "Site of action: the central nervous system."}], "teach": "The inhaled muscarinic antagonists (less systemic effect) are ipratropium, tiotropium, aclidinium and umeclidinium. In the lungs only the parasympathetic system innervates bronchial smooth muscle, where M3 causes bronchial constriction.", "quote": "Muscarinic Antagonists: Inhaled (less systemic effect) — Ipratropium; Tiotropium; Aclidinium and Umeclidinium", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3–4; PCOL-Cholinergic-26s.pdf slide 27–28"},
{"id": "DL2-043", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-oab", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of oxybutynin?", "options": [{"t": "Muscarinic antagonist favoring M3", "correct": true, "why": "Oxybutynin and the other overactive-bladder drugs are non-selective, reversible muscarinic antagonists that are more selective toward bladder M3."}, {"t": "β3 agonist in bladder smooth muscle", "correct": false, "why": "That is mirabegron."}, {"t": "Non-selective muscarinic agonist", "correct": false, "why": "That is bethanechol, used for urinary retention."}, {"t": "α1 antagonist in the urethra", "correct": false, "why": "That is prazosin, terazosin, doxazosin and tamsulosin."}], "teach": "Oxybutynin, tolterodine, fesoterodine, solifenacin, darifenacin and trospium are reversible muscarinic antagonists, more selective toward the M3 receptors in the bladder. They decrease urgency, frequency and leakage in overactive bladder.", "quote": "Muscarinic Antagonists for Overactive Bladder Disorders … MOA: Non-selective, reversible, and hepatic metabolism (3A4 or 2D6); More selective towards the M3 receptors in the bladder", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 29"},
{"id": "DL2-044", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "oab-cns", "tags": ["drug-list", "tell"], "source": "slide", "fg": "classes", "stem": "Which overactive-bladder muscarinic antagonist is most likely to cause central effects (drowsiness, dizziness, confusion)?", "options": [{"t": "Oxybutynin", "correct": true, "why": "Oxybutynin (M1 and M3) is at the top of the order of drugs with central effects."}, {"t": "Solifenacin", "correct": false, "why": "Solifenacin (M3) is in the group with the fewest central effects."}, {"t": "Darifenacin", "correct": false, "why": "Darifenacin (M3) is in the group with the fewest central effects."}, {"t": "Trospium", "correct": false, "why": "Trospium (M3) is in the group with the fewest central effects."}, {"t": "Fesoterodine", "correct": false, "why": "Fesoterodine (M1 and M3) is in the middle group, with tolterodine."}], "teach": "All overactive-bladder antagonists can cause anti-DUMBBELSS, especially dry mouth and constipation (M3). Central effects (drowsiness, dizziness, confusion) follow M1 block: oxybutynin (M1 and M3) most, then tolterodine and fesoterodine, and least solifenacin, darifenacin and trospium (M3).", "quote": "Order of drugs with CNS effects (Drowsiness, dizziness, & confusion): M1 & M3 — Oxybutynin; M1 & M3 — Tolterodine, Fesoterodine; M3 — Solifenacin, Darifenacin, Trospium", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 30", "note": "The drug list says solifenacin, darifenacin and trospium are “least likely to cause anti-DUMBBELSS”; the slide says all of them can cause anti-DUMBBELSS and places the three lowest for central effects. Keyed to the slide."},
{"id": "DL2-045", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-oab", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which adverse effects are shared by all the overactive-bladder muscarinic antagonists? Select all that apply.", "options": [{"t": "Xerostomia (dry mouth)", "correct": true, "why": "All muscarinic antagonists: M3 block on salivary glands."}, {"t": "Constipation", "correct": true, "why": "All muscarinic antagonists: M3 block in the gut."}, {"t": "Diarrhea", "correct": false, "why": "Diarrhea is a muscarinic agonist (DUMBBELSS) effect."}, {"t": "Miosis", "correct": false, "why": "Miosis is an agonist effect; antagonists dilate the pupil."}, {"t": "Bradycardia", "correct": false, "why": "Bradycardia is an agonist effect (M2); antagonists raise heart rate."}], "teach": "All overactive-bladder antagonists have the potential to cause anti-DUMBBELSS. The effects shared by all muscarinic antagonists through M3 are xerostomia (dry mouth) and constipation.", "quote": "All have the potential to cause anti-DUMBBELSS: Xerostomia (dry mouth) and constipation — M3 — All Musc. Antag", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 30"},
{"id": "DL2-046", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "no", "skill": "drug", "concept": "moa-nitrates", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of nitroglycerin?", "options": [{"t": "Donates nitric oxide, which raises cGMP", "correct": true, "why": "Listed: donate nitric oxide; nitric oxide → soluble guanylyl cyclase (sGC) → ↑ cyclic guanosine monophosphate (cGMP)."}, {"t": "Blocks phosphodiesterase, which raises cGMP", "correct": false, "why": "That is sildenafil, tadalafil and vardenafil."}, {"t": "Activates M3 receptors on the endothelium", "correct": false, "why": "That is a muscarinic agonist; nitroglycerin donates nitric oxide itself."}, {"t": "Blocks α1 receptors on blood vessels", "correct": false, "why": "That is prazosin and the other α1 antagonists."}], "teach": "Nitroglycerin, nitroprusside and isosorbide dinitrate/mononitrate are nitric oxide donors. Nitric oxide activates soluble guanylyl cyclase (sGC), which raises cyclic guanosine monophosphate (cGMP), a potent vasodilator; the result is vasodilation and lower blood pressure.", "quote": "Nitroglycerine, Nitroprusside, Isosorbide di / mononitrate (donor): Donate nitric oxide; NO → sGC → ↑cGMP; Vasodilation; Lower blood pressure; cGMP is a potent vasodilator", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4"},
{"id": "DL2-047", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "no", "skill": "drug", "concept": "moa-pde", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of sildenafil?", "options": [{"t": "Blocks phosphodiesterase, so cGMP rises", "correct": true, "why": "Listed: blocks phosphodiesterase (PDE), the enzyme that breaks down cyclic guanosine monophosphate (cGMP), so there is more cGMP."}, {"t": "Donates nitric oxide, so cGMP rises", "correct": false, "why": "That is nitroglycerin, nitroprusside and isosorbide."}, {"t": "Blocks muscarinic M3 receptors on vessels", "correct": false, "why": "That is a muscarinic antagonist."}, {"t": "Activates β2 receptors on vascular smooth muscle", "correct": false, "why": "That is the β2 agonists (albuterol and others)."}], "teach": "Sildenafil, tadalafil and vardenafil block phosphodiesterase (PDE), the enzyme that breaks down cyclic guanosine monophosphate (cGMP). More cGMP gives vasodilation and lower blood pressure; they are used for erectile dysfunction. The list colours them as indirect antagonists.", "quote": "Sildenafil, Tadalafil, Vardenafil (indirect antagonist): Blocks PDE → increase cGMP; Vasodilation; Lower blood pressure; Blocks enzyme that breaks down cGMP = more cGMP", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4"},
{"id": "DL2-048", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "no", "skill": "drug", "concept": "group-cgmp", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs lower blood pressure by raising cGMP in blood vessels? Select all that apply.", "options": [{"t": "Nitroprusside", "correct": true, "why": "Nitric oxide donor → soluble guanylyl cyclase → ↑ cyclic guanosine monophosphate (cGMP)."}, {"t": "Isosorbide mononitrate", "correct": true, "why": "Nitric oxide donor → ↑ cGMP."}, {"t": "Tadalafil", "correct": true, "why": "Blocks phosphodiesterase → ↑ cGMP."}, {"t": "Prazosin", "correct": false, "why": "Prazosin lowers blood pressure by blocking α1 receptors, not through cGMP."}, {"t": "Bethanechol", "correct": false, "why": "A muscarinic agonist used for urinary retention."}, {"t": "Atropine", "correct": false, "why": "A muscarinic antagonist."}], "teach": "Two groups on the list end in more cyclic guanosine monophosphate (cGMP): nitric oxide donors (nitroglycerin, nitroprusside, isosorbide), which make more of it, and phosphodiesterase blockers (sildenafil, tadalafil, vardenafil), which stop its breakdown. Both give vasodilation and lower blood pressure.", "quote": "Donate nitric oxide; NO → sGC → ↑cGMP … Blocks PDE → increase cGMP … Vasodilation; Lower blood pressure", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4"},
{"id": "DL2-049", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-phenylephrine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of phenylephrine?", "options": [{"t": "α1 agonist", "correct": true, "why": "Phenylephrine is listed as an α1 agonist acting on blood vessels and the eye."}, {"t": "α2 agonist", "correct": false, "why": "That is clonidine, brimonidine, tizanidine, guanfacine and dexmedetomidine."}, {"t": "Selective α1 antagonist", "correct": false, "why": "That is prazosin, terazosin, doxazosin and tamsulosin."}, {"t": "β1 agonist", "correct": false, "why": "That is dobutamine."}], "teach": "Phenylephrine activates α1 receptors on blood vessels (vasoconstriction; nasal decongestant) and in the eye (mydriasis). Its adverse reactions are hypertension, burning and nasal discharge, and rebound congestion from receptor down-regulation.", "quote": "Phenylephrine (agonist): α1 agonist; SOA: Blood vessels, Eyes", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4"},
{"id": "DL2-050", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-phenylephrine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which adverse reaction is listed for phenylephrine used as a nasal decongestant?", "options": [{"t": "Rebound congestion from receptor down-regulation", "correct": true, "why": "Listed: down-regulation → rebound congestion."}, {"t": "Orthostatic hypotension followed by reflex tachycardia", "correct": false, "why": "That is the α1 antagonists (prazosin and others)."}, {"t": "Bronchospasm in asthma patients", "correct": false, "why": "That is the non-selective β blockers (propranolol and others)."}, {"t": "Peripheral edema", "correct": false, "why": "That is mirtazapine (α2 block in small blood vessels)."}], "teach": "Phenylephrine’s listed adverse reactions are hypertension, burning and nasal discharge, and rebound congestion. Repeated α1 activation down-regulates the receptors, which gives rebound congestion; the list says to avoid it in patients with hypertension.", "quote": "HTN, Burning & nasal discharge, rebound congestion … Down-reg → rebound congestion; Avoid in patients with HTN", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4"},
{"id": "DL2-051", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-cocaine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of cocaine?", "options": [{"t": "Norepinephrine reuptake inhibitor", "correct": true, "why": "Listed: NE (norepinephrine) reuptake inhibitor, an indirect-acting drug."}, {"t": "Stimulates presynaptic release of norepinephrine and dopamine", "correct": false, "why": "That is amphetamine and methylphenidate."}, {"t": "Irreversible inhibitor of MAO-A and MAO-B", "correct": false, "why": "That is phenelzine (monoamine oxidase inhibitor)."}, {"t": "α1 agonist", "correct": false, "why": "That is phenylephrine, a direct agonist."}], "teach": "Cocaine blocks reuptake of norepinephrine, so more norepinephrine stays in the synapse; its site of action is the central nervous system. Its listed adverse reactions are hypertension, tachycardia, arrhythmias and restlessness.", "quote": "Cocaine (indirect antagonist): NE reuptake inhibitor; CNS; HTN, tachycardia, arrythmias, restlessness", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5"},
{"id": "DL2-052", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-amphetamine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of methylphenidate?", "options": [{"t": "Stimulates release of norepinephrine and dopamine", "correct": true, "why": "Listed for amphetamine, lisdexamphetamine, methylphenidate and dexmethylphenidate."}, {"t": "Norepinephrine reuptake inhibitor", "correct": false, "why": "That is cocaine."}, {"t": "Selective, irreversible monoamine oxidase B inhibitor", "correct": false, "why": "That is selegiline and rasagiline."}, {"t": "Central α2 agonist", "correct": false, "why": "That is clonidine and guanfacine."}], "teach": "Dextroamphetamine/amphetamine, methylphenidate, lisdexamphetamine and dexmethylphenidate stimulate presynaptic release of norepinephrine and dopamine in the central nervous system. Adverse reactions: hypertension, tachycardia, arrhythmias, restlessness and loss of appetite.", "quote": "Stimulate pre-synaptic release of NE & DA (indirect antagonist); CNS; HTN, tachycardia, arrythmias, restlessness, loss of appetite", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5"},
{"id": "DL2-053", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "phenelzine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about phenelzine is CORRECT?", "options": [{"t": "It can cause a hypertensive crisis with dietary tyramine", "correct": true, "why": "Listed serious adverse reaction: hypertensive crisis due to dietary tyramine."}, {"t": "It is a selective, reversible monoamine oxidase B inhibitor", "correct": false, "why": "Phenelzine is non-selective (MAO-A and MAO-B) and irreversible; selegiline and rasagiline are the selective MAO-B drugs."}, {"t": "It blocks norepinephrine reuptake", "correct": false, "why": "That is cocaine."}, {"t": "It is a direct α1 agonist", "correct": false, "why": "That is phenylephrine."}], "teach": "Phenelzine irreversibly inhibits both monoamine oxidase A and B (MAO-A and MAO-B), so the breakdown of norepinephrine is inhibited. Its serious adverse reaction is a hypertensive crisis from dietary tyramine; the list notes phenoxybenzamine can be used short term for that crisis.", "quote": "Phenelzine: Non-selective MOA-A & MOA-B irreversible antagonist; Inhibits breakdown of NE; Serious ADR → HTN crisis due to dietary Tyramine", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5"},
{"id": "DL2-054", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mao-tell", "tags": ["drug-list", "tell"], "source": "slide", "fg": "classes", "stem": "Which drug is a selective, irreversible inhibitor of monoamine oxidase B (MAO-B)?", "options": [{"t": "Selegiline", "correct": true, "why": "Selegiline and rasagiline: selective MAO-B irreversible antagonists."}, {"t": "Phenelzine", "correct": false, "why": "Phenelzine inhibits both MAO-A and MAO-B (non-selective)."}, {"t": "Cocaine", "correct": false, "why": "Cocaine is a norepinephrine reuptake inhibitor."}, {"t": "Mirtazapine", "correct": false, "why": "Mirtazapine is an α2 (and α1, muscarinic, H1, 5-HT2a) antagonist."}], "teach": "Both monoamine oxidase (MAO) drug groups inhibit breakdown of norepinephrine and are irreversible. Phenelzine blocks MAO-A and MAO-B (non-selective); selegiline and rasagiline block MAO-B selectively and are listed for depression and Parkinson’s.", "quote": "Selegiline, Rasagiline: SELECTIVE MAO-B irreversible antagonist; Inhibits breakdown of NE", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5"},
{"id": "DL2-055", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-indirect-adr", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs raise synaptic norepinephrine indirectly rather than binding adrenergic receptors? Select all that apply.", "options": [{"t": "Cocaine", "correct": true, "why": "Norepinephrine reuptake inhibitor."}, {"t": "Methylphenidate", "correct": true, "why": "Stimulates presynaptic release of norepinephrine and dopamine."}, {"t": "Phenelzine", "correct": true, "why": "Inhibits monoamine oxidase, the enzyme that breaks down norepinephrine."}, {"t": "Rasagiline", "correct": true, "why": "Inhibits monoamine oxidase B (MAO-B)."}, {"t": "Phenylephrine", "correct": false, "why": "A direct α1 agonist."}, {"t": "Clonidine", "correct": false, "why": "A direct α2 agonist."}, {"t": "Prazosin", "correct": false, "why": "A direct α1 antagonist."}], "teach": "The list’s indirect adrenergic drugs act on norepinephrine handling, not on the receptor: cocaine blocks reuptake; amphetamines and methylphenidate stimulate release; phenelzine, selegiline and rasagiline inhibit breakdown by monoamine oxidase (MAO).", "quote": "Cocaine: NE reuptake inhibitor. Amphetamine/Methylphenidate: Stimulate pre-synaptic release of NE & DA. Phenelzine, Selegiline, Rasagiline: Inhibits breakdown of NE", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5"},
{"id": "DL2-056", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-prazosin", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of doxazosin?", "options": [{"t": "Selective, reversible α1 antagonist", "correct": true, "why": "Prazosin, terazosin, doxazosin and tamsulosin (α1a) are selective, reversible α1 antagonists."}, {"t": "Non-selective, irreversible α1 and α2 antagonist", "correct": false, "why": "That is phenoxybenzamine."}, {"t": "α2 agonist", "correct": false, "why": "That is clonidine and the related α2 agonists."}, {"t": "β1, β2 and α1 antagonist", "correct": false, "why": "That is carvedilol and labetalol."}], "teach": "Prazosin, terazosin, doxazosin and tamsulosin block α1 receptors selectively and reversibly (tamsulosin is listed for α1a). Sites listed: brain, eye, nose, blood vessels and urethra. Blocking α1 on blood vessels decreases preload and afterload.", "quote": "Prazosin, Terazosin, Doxazosin, Tamsulosin → α1a: SELECTIVE α1 antagonist reversible", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5"},
{"id": "DL2-057", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-alpha1-block", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which adverse reaction is listed for the selective α1 antagonists such as prazosin?", "options": [{"t": "Orthostatic hypotension leading to reflex tachycardia", "correct": true, "why": "Listed with headache, blurred vision and sexual dysfunction."}, {"t": "Rebound congestion", "correct": false, "why": "That is phenylephrine (α1 agonist)."}, {"t": "Hypertensive crisis when the drug is stopped abruptly", "correct": false, "why": "That is the α2 agonists (clonidine and others)."}, {"t": "Masking of hypoglycemia symptoms", "correct": false, "why": "That is the non-selective β blockers and carvedilol/labetalol."}], "teach": "Blocking α1 on blood vessels lowers resistance; on standing this gives orthostatic hypotension, followed by reflex tachycardia. The other listed reactions of the α1 antagonists are headache, blurred vision and sexual dysfunction.", "quote": "Headache; Blurred vision; Orthostatic hypotension → reflex tachycardia; Sexual dysfunction", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5"},
{"id": "DL2-058", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "phenoxybenzamine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about phenoxybenzamine is CORRECT?", "options": [{"t": "It blocks α1 and α2 irreversibly", "correct": true, "why": "Listed: non-selective α1 and α2 antagonist, irreversible, with a longer duration of action."}, {"t": "It blocks α1 selectively and reversibly", "correct": false, "why": "That is prazosin, terazosin, doxazosin and tamsulosin."}, {"t": "It activates α2 receptors in the brain", "correct": false, "why": "Activating central α2 is clonidine and the related agonists."}, {"t": "It blocks β1 and β2 receptors", "correct": false, "why": "That is propranolol, pindolol and timolol."}], "teach": "Phenoxybenzamine blocks α1 and α2 non-selectively and irreversibly, which decreases peripheral resistance and gives a longer duration of action. The list notes its α2 block on parasympathetic fibers causes gastrointestinal stimulation, and that it can control a phenelzine hypertensive crisis short term.", "quote": "Phenoxybenzamine: Non-selective α1 & α2 antagonist irreversible; Decrease peripheral resistance; Longer duration of action (irreversible → highest affinity for α1)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5–6"},
{"id": "DL2-059", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "phenoxybenzamine-gi", "tags": ["drug-list", "apply"], "source": "slide", "fg": "classes", "stem": "Phenoxybenzamine causes gastrointestinal (GI) stimulation. Which explanation does the drug list give?", "options": [{"t": "α2 on parasympathetic fibers is blocked", "correct": true, "why": "Listed: “GI stimulation (α2 on PNS fiber blocked)”; the list’s α2-agonist row gives the reverse: less acetylcholine in the gut."}, {"t": "α1 receptors on gut smooth muscle are activated", "correct": false, "why": "Phenoxybenzamine is an antagonist; it does not activate receptors."}, {"t": "Acetylcholinesterase in the gut is inhibited", "correct": false, "why": "That is the cholinesterase inhibitors."}, {"t": "M3 receptors in the gut are blocked", "correct": false, "why": "Blocking gut M3 causes constipation, not stimulation."}], "teach": "The drug list explains phenoxybenzamine’s GI stimulation by α2 block on parasympathetic (PNS) fibers. The α2-agonist row states the opposite direction: α2 activation works through a GI inhibitory negative-feedback pathway that leaves less acetylcholine, giving constipation.", "quote": "GI stimulation (α2 on PNS fiber blocked). [α2 agonists:] constipation (activates GI inhibitory negative feedback pathway → less Ach)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6"},
{"id": "DL2-060", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mirtazapine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which receptor does mirtazapine block to cause drowsiness?", "options": [{"t": "H1", "correct": true, "why": "Listed: blocks H1 → drowsiness."}, {"t": "α1", "correct": false, "why": "Mirtazapine blocks α1 too, but the list ties drowsiness to H1 block."}, {"t": "α2", "correct": false, "why": "α2 block enhances release of norepinephrine and serotonin; the list ties drowsiness to H1."}, {"t": "β1", "correct": false, "why": "Mirtazapine is not listed as acting at β receptors."}], "teach": "Mirtazapine is a non-selective antagonist at α2, α1, muscarinic, H1 and 5-HT2a receptors, acting in the central nervous system. α2 block enhances release of norepinephrine and serotonin; H1 block causes drowsiness.", "quote": "Mirtazapine: NON-SELECTIVE α2 antagonist, α1 antagonist, Muscarinic antagonist, H1 antagonist, 5-HT2a antagonist; Enhances release of NE & 5-HT (serotonin); Blocks H1 release → drowsiness", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6"},
{"id": "DL2-061", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mirtazapine-edema", "tags": ["drug-list", "apply"], "source": "slide", "fg": "classes", "stem": "Why does mirtazapine cause peripheral edema?", "options": [{"t": "α2 block in small vessels dilates them", "correct": true, "why": "Listed: α2 in small blood vessels causes vasoconstriction, so the antagonist causes vasodilation → peripheral edema."}, {"t": "H1 block in the brain causes fluid retention", "correct": false, "why": "The list ties H1 block to drowsiness."}, {"t": "Muscarinic block in the gut causes edema", "correct": false, "why": "Muscarinic block is tied to xerostomia and constipation."}, {"t": "α1 activation in the kidney retains sodium", "correct": false, "why": "Mirtazapine blocks α1; it does not activate it."}], "teach": "The list explains mirtazapine’s peripheral edema through α2: α2 receptors in small blood vessels cause vasoconstriction, so blocking them causes vasodilation and fluid collects peripherally. Other listed reactions are drowsiness, weight gain, increased cholesterol, xerostomia, constipation and hypertension.", "quote": "α2’s located in small blood vessels cause vasoconstriction → antagonist will cause vasodilation → peripheral edema", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6"},
{"id": "DL2-062", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-clonidine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of guanfacine?", "options": [{"t": "α2 agonist", "correct": true, "why": "Clonidine, brimonidine, tizanidine, guanfacine and dexmedetomidine are α2 agonists."}, {"t": "α2 antagonist", "correct": false, "why": "That is mirtazapine."}, {"t": "α1 agonist", "correct": false, "why": "That is phenylephrine."}, {"t": "β1 antagonist", "correct": false, "why": "That is metoprolol, atenolol and nebivolol."}], "teach": "The α2 agonists act in the central nervous system, where they enhance inhibition and suppress the sympathetic nervous system. Their listed adverse reactions are sedation, dry mouth, hypotension, bradycardia, sexual dysfunction, depression and constipation.", "quote": "Clonidine, Brimonidine, Tizanidine, Guanfacine, Dexmedetomidine: α2 agonist; CNS; Enhance inhibitory / suppress SNS", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6"},
{"id": "DL2-063", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "clonidine-withdrawal", "tags": ["drug-list", "apply"], "source": "slide", "fg": "classes", "stem": "A patient stops clonidine abruptly. Which reaction is listed, and why?", "options": [{"t": "Hypertensive crisis, from up-regulated receptors", "correct": true, "why": "Listed: hypertensive crisis can occur if taken off drug abruptly due to up-regulation of receptors."}, {"t": "Bronchospasm, from β2 block", "correct": false, "why": "Bronchospasm risk is the non-selective β blockers; clonidine is an α2 agonist."}, {"t": "Rebound congestion, from down-regulated α1 receptors", "correct": false, "why": "That is phenylephrine."}, {"t": "Hypoglycemia, from masked symptoms", "correct": false, "why": "Masked hypoglycemia is the β blockers."}], "teach": "Clonidine activates central α2 receptors and suppresses sympathetic outflow. During treatment the receptors up-regulate, so stopping the drug abruptly can cause a hypertensive crisis.", "quote": "Hypertensive crisis can occur if taken off drug abruptly due to up-regulation of receptors", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6"},
{"id": "DL2-064", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-alpha2-agonist", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which adverse reactions are listed for the α2 agonists such as clonidine? Select all that apply.", "options": [{"t": "Sedation", "correct": true, "why": "Listed."}, {"t": "Dry mouth", "correct": true, "why": "Listed."}, {"t": "Bradycardia", "correct": true, "why": "Listed (suppressed sympathetic outflow)."}, {"t": "Hypotension", "correct": true, "why": "Listed."}, {"t": "Tachycardia and arrhythmias", "correct": false, "why": "Those are the indirect sympathomimetics (cocaine, amphetamines) and dobutamine."}, {"t": "Rebound nasal congestion", "correct": false, "why": "That is phenylephrine."}], "teach": "α2 agonists suppress the sympathetic nervous system from the central nervous system. Listed reactions: sedation, dry mouth, hypotension, bradycardia, sexual dysfunction, depression and constipation (the list says through a gastrointestinal inhibitory feedback pathway → less acetylcholine).", "quote": "Sedation, dry mouth, hypotension, bradycardia, sexual dysfunction, depression, constipation", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6"},
{"id": "DL2-065", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-dobutamine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which drug is a β1 agonist that is β1 selective at low dose?", "options": [{"t": "Dobutamine", "correct": true, "why": "Listed: β1 agonist; low dose β1 selective; high dose β1 > β2 > α1."}, {"t": "Isoproterenol", "correct": false, "why": "Isoproterenol is a β1 and β2 agonist."}, {"t": "Albuterol", "correct": false, "why": "Albuterol is a β2 agonist."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is a selective β1 antagonist."}], "teach": "Dobutamine activates β1 in the heart (increased heart rate and contractility). At low dose it is β1 selective; at high dose it acts at β1 > β2 > α1. The list notes tachycardia, arrhythmias, increased renin–angiotensin–aldosterone system (RAAS) activity and central nervous system stimulation as effects.", "quote": "Dobutamine: β1 agonist; LOW dose: β1 selective; HIGH dose: β1 > β2 > α1", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6"},
{"id": "DL2-066", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-metoprolol", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Atenolol, metoprolol and nebivolol (“MAN”) share which mechanism of action?", "options": [{"t": "Selective β1 antagonist", "correct": true, "why": "Listed as the selective β1 blockers."}, {"t": "Non-selective β1 and β2 antagonist", "correct": false, "why": "That is propranolol, pindolol and timolol."}, {"t": "β1, β2 and α1 antagonist", "correct": false, "why": "That is carvedilol and labetalol."}, {"t": "β1 agonist", "correct": false, "why": "That is dobutamine."}], "teach": "Metoprolol, atenolol and nebivolol block β1 selectively; their listed sites are the heart, kidneys and brain. Adverse reactions follow from β1 block: decreased heart rate and contractility, bradycardia, fatigue or dizziness, decreased renin–angiotensin–aldosterone system (RAAS) activity and central nervous system (CNS) depression.", "quote": "Metoprolol, Atenolol, Nebivolol “MAN”: SELECTIVE β1 antagonist “β1 beta-blockers”; Heart, Kidneys, Brain", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6–7"},
{"id": "DL2-067", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-beta1-block", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which adverse reaction is listed for the selective β1 antagonists such as atenolol?", "options": [{"t": "Bradycardia", "correct": true, "why": "Listed with decreased heart rate and contractility, fatigue/dizziness, decreased RAAS and CNS depression."}, {"t": "Tachycardia", "correct": false, "why": "Tachycardia is a β1 agonist (dobutamine) effect."}, {"t": "Orthostatic hypotension with reflex tachycardia", "correct": false, "why": "That is the α1 antagonists."}, {"t": "Rebound congestion", "correct": false, "why": "That is phenylephrine."}], "teach": "Selective β1 antagonists act on the heart, kidneys and brain. Blocking β1 in the heart decreases heart rate and contractility (bradycardia); in the kidney it decreases the renin–angiotensin–aldosterone system (RAAS); in the brain it gives fatigue, dizziness and central nervous system (CNS) depression.", "quote": "Decreased heart rate and contractility; Fatigue / dizziness; Bradycardia; Decreased RAAS; CNS depression", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6–7"},
{"id": "DL2-068", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "saba-laba", "tags": ["drug-list", "tell", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs are long-acting β2 agonists (LABA)? Select all that apply.", "options": [{"t": "Salmeterol", "correct": true, "why": "Listed under LABA."}, {"t": "Formoterol", "correct": true, "why": "Listed under LABA."}, {"t": "Albuterol", "correct": false, "why": "Listed under SABA (short-acting β2 agonist)."}, {"t": "Levalbuterol", "correct": false, "why": "Listed under SABA (short-acting β2 agonist)."}, {"t": "Tiotropium", "correct": false, "why": "Tiotropium is a long-acting muscarinic antagonist, not a β2 agonist."}], "teach": "The list’s β2 agonists are short-acting (SABA: albuterol, levalbuterol) and long-acting (LABA: salmeterol, formoterol). Sites: lungs, vasculature and the central nervous system; effects: bronchial dilation, vasodilation and excitation.", "quote": "SABA: Albuterol (Ventolin), Levalbuterol (Xopenex). LABA: Salmeterol, Formoterol. β2 agonist", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7"},
{"id": "DL2-069", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "soa-beta2", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Albuterol is a β2 agonist. Which effects are listed for the β2 agonists? Select all that apply.", "options": [{"t": "Bronchial dilation", "correct": true, "why": "Listed (lungs)."}, {"t": "Vasodilation", "correct": true, "why": "Listed (vasculature)."}, {"t": "Excitation", "correct": true, "why": "Listed (central nervous system)."}, {"t": "Bronchial constriction", "correct": false, "why": "Bronchial constriction comes from M3 activation; β2 dilates."}, {"t": "Bradycardia", "correct": false, "why": "Bradycardia is a β1-blocker or muscarinic agonist effect."}], "teach": "The β2 agonists act on the lungs, vasculature and central nervous system. The listed effects are bronchial dilation, vasodilation and excitation.", "quote": "β2 agonist; Lungs, Vasculature, CNS; Bronchial dilation, Vasodilation, Excitation", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7"},
{"id": "DL2-070", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-propranolol", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of propranolol?", "options": [{"t": "Non-selective β1 and β2 antagonist", "correct": true, "why": "Propranolol, pindolol and timolol are listed as non-selective β blockers (β1 and β2)."}, {"t": "Selective β1 antagonist", "correct": false, "why": "That is metoprolol, atenolol and nebivolol."}, {"t": "β1, β2 and α1 antagonist", "correct": false, "why": "That is carvedilol and labetalol."}, {"t": "Non-selective α1 and α2 antagonist", "correct": false, "why": "That is phenoxybenzamine."}], "teach": "Propranolol blocks β1 and β2. Its listed sites are the heart, kidneys, brain, lungs and vasculature. Because it blocks β2 in the lungs it is listed as contraindicated in asthma patients, and it masks the nervousness and tremor of hypoglycemia.", "quote": "Propranolol, Pindolol (PARTIAL AGONIST), Timolol: NON-SELECTIVE Beta-blockers; β1 & β2 antagonist", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7"},
{"id": "DL2-071", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "pindolol", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which drug in the non-selective β-blocker group is marked as a partial agonist?", "options": [{"t": "Pindolol", "correct": true, "why": "Listed as “Pindolol (PARTIAL AGONIST)” in the non-selective β1 and β2 group."}, {"t": "Propranolol", "correct": false, "why": "Propranolol is listed as a non-selective β antagonist without partial agonism."}, {"t": "Timolol", "correct": false, "why": "Timolol is listed as a non-selective β antagonist without partial agonism."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is a selective β1 antagonist."}], "teach": "Pindolol sits in the non-selective β-blocker row with propranolol and timolol but is marked as a partial agonist; the Exam 1 list also called it a β1 and β2 partial agonist. A partial agonist activates the receptor submaximally and competes with full agonists.", "quote": "Pindolol (PARTIAL AGONIST) (antagonist)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7"},
{"id": "DL2-072", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-asthma", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs are listed as contraindicated in asthma patients and as masking symptoms of hypoglycemia? Select all that apply.", "options": [{"t": "Propranolol", "correct": true, "why": "Non-selective β blocker: blocks β2 in the lungs."}, {"t": "Timolol", "correct": true, "why": "Non-selective β blocker."}, {"t": "Carvedilol", "correct": true, "why": "β1, β2 and α1 antagonist."}, {"t": "Labetalol", "correct": true, "why": "β1, β2 and α1 antagonist."}, {"t": "Albuterol", "correct": false, "why": "A β2 agonist; it dilates the bronchi."}, {"t": "Dobutamine", "correct": false, "why": "A β1 agonist."}, {"t": "Clonidine", "correct": false, "why": "A central α2 agonist."}], "teach": "The drugs that block β2 as well as β1 — propranolol, pindolol, timolol, carvedilol and labetalol — are listed as contraindicated for asthma patients and as masking symptoms of hypoglycemia (no nervousness or tremors).", "quote": "Mask symptoms of hypoglycemia → no nervousness / tremors … Contraindicated for asthma pts", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7"},
{"id": "DL2-073", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-carvedilol", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of labetalol?", "options": [{"t": "β1, β2 and α1 antagonist", "correct": true, "why": "Carvedilol and labetalol are listed as β1 and β2 antagonists and α1 antagonists."}, {"t": "Selective β1 antagonist", "correct": false, "why": "That is metoprolol, atenolol and nebivolol."}, {"t": "Selective, reversible α1 antagonist", "correct": false, "why": "That is prazosin and the related drugs."}, {"t": "β3 agonist", "correct": false, "why": "That is mirabegron."}], "teach": "Carvedilol and labetalol block β1, β2 and α1. Their listed effects follow from β block (decreased heart rate and contractility, bradycardia, fatigue, decreased renin–angiotensin–aldosterone system (RAAS) activity) and they share the asthma contraindication and the masking of hypoglycemia with the non-selective β blockers.", "quote": "Carvedilol (Coreg), Labetalol (Trandate): β1 & β2 antagonist, & α1 antagonist", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7"},
{"id": "DL2-074", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mirabegron", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which drug is a β3 agonist acting in the bladder?", "options": [{"t": "Mirabegron", "correct": true, "why": "Listed: β3 agonist; site of action the bladder; relief for overactive bladder."}, {"t": "Oxybutynin", "correct": false, "why": "Oxybutynin is a muscarinic antagonist at bladder M3."}, {"t": "Bethanechol", "correct": false, "why": "Bethanechol is a muscarinic agonist (urinary retention)."}, {"t": "Tamsulosin", "correct": false, "why": "Tamsulosin is an α1 (α1a) antagonist."}], "teach": "Mirabegron activates β3 receptors in the bladder and relieves overactive bladder. The list notes it has fewer side effects than the muscarinic antagonists used for the same problem.", "quote": "Mirabegron: β3 agonist; Bladder; Relief for overactive bladder; Less side effects than muscarinic antagonists", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7"},
{"id": "DL2-075", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "oab-tell", "tags": ["drug-list", "tell"], "source": "slide", "fg": "classes", "stem": "Two drugs for overactive bladder: oxybutynin and mirabegron. Which statement tells them apart?", "options": [{"t": "Oxybutynin blocks M3; mirabegron activates β3", "correct": true, "why": "Oxybutynin: muscarinic antagonist, more selective for bladder M3. Mirabegron: β3 agonist in the bladder."}, {"t": "Oxybutynin activates β3; mirabegron blocks M3", "correct": false, "why": "Reverses the two mechanisms."}, {"t": "Both block M3 in the bladder", "correct": false, "why": "Only oxybutynin is a muscarinic antagonist."}, {"t": "Both activate β3 in the bladder", "correct": false, "why": "Only mirabegron is a β3 agonist."}], "teach": "Oxybutynin is a muscarinic antagonist (more selective toward bladder M3) and can cause anti-DUMBBELSS, especially dry mouth and constipation. Mirabegron is a β3 agonist in the bladder with fewer side effects than the muscarinic antagonists.", "quote": "Oxybutynin … More selective towards the M3 receptors in the bladder. Mirabegron: β3 agonist; Bladder; Less side effects than muscarinic antagonists", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4, 7; PCOL-Cholinergic-26s.pdf slide 29"},
{"id": "DL2-076", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "epinephrine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about epinephrine’s receptor actions is CORRECT?", "options": [{"t": "β1, β2 at low dose; all at high dose", "correct": true, "why": "Listed: low dose β1 & β2; high dose: everything."}, {"t": "α1 only at every dose", "correct": false, "why": "α1 alone is phenylephrine."}, {"t": "β1 only at low dose; β1 > β2 > α1 at high dose", "correct": false, "why": "That is dobutamine."}, {"t": "α2 only, acting in the brain", "correct": false, "why": "α2 agonism in the brain is clonidine and the related drugs."}], "teach": "Epinephrine is released from the adrenal medulla and acts at β2 on smooth muscle (bronchial dilation, vasodilation). The drug list gives β1 and β2 at low dose and all adrenergic receptors at high dose, used for shock and anaphylaxis; patients must be weaned off because the receptors down-regulate.", "quote": "Epinephrine: β1, β2 agonist (blood vessels); Low dose: β1 & β2; High dose: everything. β2 Agonists - Epinephrine", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8; Autonomic Nervous System.pdf slide 35, 42", "note": "The Exam 1 drug list called epinephrine an α1, α2, β1 and β2 agonist; this list gives β1 and β2 at low dose and all receptors at high dose. The autonomic slides show epinephrine at β2 only. Re-check against the adrenergic deck when it is available."},
{"id": "DL2-077", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "norepinephrine", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Norepinephrine released from sympathetic nerves acts as an agonist at which receptors?", "options": [{"t": "α1, α2 and β1", "correct": true, "why": "Norepinephrine is the neurotransmitter at α1, α2 and β1; β2 is “typically not innervated”. In the gut, norepinephrine acts at α2 to inhibit acetylcholine release."}, {"t": "α1 and β1 only", "correct": false, "why": "Leaves out α2 (presynaptic sympathetic neurons, brain, gut)."}, {"t": "β1 and β2 only", "correct": false, "why": "That is isoproterenol."}, {"t": "α1 only", "correct": false, "why": "That is phenylephrine."}], "teach": "Norepinephrine is the adrenergic neurotransmitter at α1 (blood vessels), α2 (presynaptic sympathetic neurons, brain, gut) and β1 (heart, kidney). β2 receptors are typically not innervated. The drug list adds increased total peripheral resistance, heart rate and contractility, used for shock.", "quote": "Adrenergic — Norepinephrine — α1, α2, β1; β2 Typically Not innervated. SNS — NE — α2 = Inhibition of Ach Release", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8; Autonomic Nervous System.pdf slide 13, 45", "note": "The drug list gives norepinephrine as an α1, β1 agonist. The autonomic slides show it acting at α1, α2 and β1 (and at α2 in the gut). Keyed to the slides. The Exam 1 drug list called it an α1, α2, β1 and β2 agonist."},
{"id": "DL2-078", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "isoproterenol", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which drug is listed as a β1 and β2 agonist that can cause hyperglycemia, palpitations and tachycardia?", "options": [{"t": "Isoproterenol", "correct": true, "why": "Listed: β1, β2 agonist (lungs); heart and lungs; hyperglycemia, palpitations, tachycardia, arrhythmias."}, {"t": "Dobutamine", "correct": false, "why": "Dobutamine is β1 selective at low dose."}, {"t": "Phenylephrine", "correct": false, "why": "Phenylephrine is an α1 agonist."}, {"t": "Propranolol", "correct": false, "why": "Propranolol blocks β1 and β2."}], "teach": "Isoproterenol activates β1 and β2; its listed sites are the heart and lungs. Its listed adverse reactions are hyperglycemia, palpitations, tachycardia and arrhythmias.", "quote": "Isoproterenol: β1, β2 agonist (lungs); Heart & lungs; Hyperglycemia, Palpitations, Tachycardia, Arrythmias", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8"},
{"id": "DL2-079", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-alpha-block", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs block α1 receptors? Select all that apply.", "options": [{"t": "Terazosin", "correct": true, "why": "Selective, reversible α1 antagonist."}, {"t": "Phenoxybenzamine", "correct": true, "why": "Non-selective α1 and α2 antagonist, irreversible."}, {"t": "Carvedilol", "correct": true, "why": "β1, β2 and α1 antagonist."}, {"t": "Mirtazapine", "correct": true, "why": "Listed as an α1 antagonist among its receptors."}, {"t": "Phenylephrine", "correct": false, "why": "Phenylephrine activates α1."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol blocks β1 only."}, {"t": "Clonidine", "correct": false, "why": "Clonidine activates α2."}], "teach": "α1 block appears in four rows of the list: the selective α1 antagonists (prazosin, terazosin, doxazosin, tamsulosin), phenoxybenzamine (α1 and α2, irreversible), carvedilol and labetalol (with β1 and β2), and mirtazapine (with α2, muscarinic, H1 and 5-HT2a).", "quote": "SELECTIVE α1 antagonist reversible … Non-selective α1 & α2 antagonist irreversible … β1 & β2 antagonist, & α1 antagonist … α1 antagonist (mirtazapine)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5–7"},
{"id": "DL2-080", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-beta-agonists", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which drugs are β agonists? Select all that apply.", "options": [{"t": "Dobutamine", "correct": true, "why": "β1 agonist."}, {"t": "Levalbuterol", "correct": true, "why": "β2 agonist (SABA)."}, {"t": "Mirabegron", "correct": true, "why": "β3 agonist."}, {"t": "Isoproterenol", "correct": true, "why": "β1 and β2 agonist."}, {"t": "Pindolol", "correct": false, "why": "Listed in the β-blocker row (marked partial agonist), coloured as an antagonist."}, {"t": "Nebivolol", "correct": false, "why": "Selective β1 antagonist."}, {"t": "Labetalol", "correct": false, "why": "β1, β2 and α1 antagonist."}], "teach": "The β agonists on the list are dobutamine (β1), albuterol, levalbuterol, salmeterol and formoterol (β2), mirabegron (β3), isoproterenol (β1, β2) and epinephrine (β1, β2 at low dose). Pindolol is listed with the β blockers although marked as a partial agonist.", "quote": "Dobutamine: β1 agonist. SABA/LABA: β2 agonist. Mirabegron: β3 agonist. Isoproterenol: β1, β2 agonist", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6–8"},
{"id": "DL2-081", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "aliskiren", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of aliskiren?", "options": [{"t": "Selective, reversible renin inhibitor", "correct": true, "why": "Listed: selective renin inhibitor, reversible; renin is the first and rate-limiting step of the RAAS pathway."}, {"t": "Angiotensin-converting enzyme inhibitor", "correct": false, "why": "That is captopril, enalapril, lisinopril and the other “-prils”."}, {"t": "Angiotensin II (AT1) receptor blocker", "correct": false, "why": "That is losartan, valsartan and the other “-sartans”."}, {"t": "Mineralocorticoid receptor antagonist", "correct": false, "why": "That is spironolactone and eplerenone."}], "teach": "Aliskiren inhibits renin in the blood stream; renin is the first and rate-limiting enzyme of the renin–angiotensin–aldosterone system (RAAS). It has low bioavailability but high affinity for renin, and it lowers total peripheral resistance and aldosterone.", "quote": "Aliskiren: Selective Renin inhibitor; REVERSIBLE antagonist; Blood stream (Renin - 1st step in RAAS pathway); Renin is the rate limiting enzyme for the RAAS pathway", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8"},
{"id": "DL2-082", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "acei", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of lisinopril?", "options": [{"t": "Reversible angiotensin-converting enzyme inhibitor", "correct": true, "why": "Listed: ACE inhibitor, reversible; ACE converts angiotensin I to angiotensin II and breaks down bradykinin."}, {"t": "Reversible angiotensin II type 1 (AT1) receptor blocker", "correct": false, "why": "That is losartan and the other angiotensin receptor blockers."}, {"t": "Selective renin inhibitor", "correct": false, "why": "That is aliskiren."}, {"t": "Selective β1 blocker in the kidney", "correct": false, "why": "That is metoprolol, which lowers renin production."}], "teach": "Captopril, enalapril, lisinopril, benazepril, quinapril and ramipril inhibit angiotensin-converting enzyme (ACE), which converts angiotensin I to angiotensin II and breaks down bradykinin. Less angiotensin II lowers total peripheral resistance and aldosterone; most are pro-drugs.", "quote": "ACE inhibitor (Angiotensin converting enzyme inhibitor); REVERSIBLE antagonists. Primary effect: inhibit ACE (ACE converts Ang I to Ang II & breaks down bradykinin)", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9"},
{"id": "DL2-083", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "acei-cough", "tags": ["drug-list", "apply"], "source": "slide", "fg": "classes", "stem": "Why do angiotensin-converting enzyme (ACE) inhibitors such as enalapril cause a dry cough?", "options": [{"t": "ACE no longer breaks down bradykinin", "correct": true, "why": "Listed: increased levels of bradykinin (a dilator) → dry cough."}, {"t": "Angiotensin II activates AT1 in the airway", "correct": false, "why": "ACE inhibitors lower angiotensin II."}, {"t": "Aldosterone rises and retains sodium", "correct": false, "why": "ACE inhibitors lower aldosterone."}, {"t": "β2 receptors in the lungs are blocked", "correct": false, "why": "β2 block in the lungs is the non-selective β blockers."}], "teach": "Angiotensin-converting enzyme (ACE) also breaks down bradykinin. Inhibiting ACE raises bradykinin, a dilator, which is the list’s explanation for the dry cough. The other listed reactions are hyperkalemia, angioedema, first-dose hypotension and fetopathic potential.", "quote": "Bonus effect 2: Increase levels of bradkykinin (dilator) → dry cough", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9"},
{"id": "DL2-084", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "arb", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which of the following describes the mechanism of action of losartan?", "options": [{"t": "Reversible angiotensin II (AT1) receptor blocker", "correct": true, "why": "Listed: ARB (angiotensin II receptor blocker), reversible; primary effect: block AT1."}, {"t": "Reversible angiotensin-converting enzyme inhibitor", "correct": false, "why": "That is the “-prils” (captopril, lisinopril and others)."}, {"t": "Selective renin inhibitor", "correct": false, "why": "That is aliskiren."}, {"t": "Mineralocorticoid receptor antagonist", "correct": false, "why": "That is spironolactone and eplerenone."}], "teach": "Losartan, valsartan, olmesartan, telmisartan and irbesartan are angiotensin II receptor blockers (ARBs) with high affinity for AT1. Blocking AT1 lowers total peripheral resistance and aldosterone, and more AT2 activation opposes AT1. Losartan is active and turns into an even more active metabolite.", "quote": "ARB (Angiotensin II receptor blocker); REVERSIBLE antagonists. Primary effect: Block AT1. Bonus effect 1: increase AT2 activation (oppose AT1). High affinity for AT1", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9"},
{"id": "DL2-085", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "acei-vs-arb", "tags": ["drug-list", "tell"], "source": "slide", "fg": "classes", "stem": "Which adverse reaction is listed for ACE inhibitors but not for angiotensin II receptor blockers (ARBs)?", "options": [{"t": "Dry cough", "correct": true, "why": "Listed for ACE (angiotensin-converting enzyme) inhibitors, from increased bradykinin; not listed for ARBs."}, {"t": "Hyperkalemia", "correct": false, "why": "Listed for both groups."}, {"t": "Angioedema", "correct": false, "why": "Listed for both groups."}, {"t": "Lower aldosterone", "correct": false, "why": "Listed as an effect of both groups."}], "teach": "Both groups lower total peripheral resistance and aldosterone and are listed with hyperkalemia and angioedema. Only the ACE (angiotensin-converting enzyme) inhibitors raise bradykinin, which the list ties to dry cough; for ARBs it lists only hyperkalemia and angioedema.", "quote": "ACE inhibitor: Dry cough, hyperkalemia, angioedema, first dose hypotension, fetopathic potential. ARB: Hyperkalemia, angioedema", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9"},
{"id": "DL2-086", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "spironolactone", "tags": ["drug-list"], "source": "slide", "fg": "classes", "stem": "Which statement about spironolactone and eplerenone is CORRECT?", "options": [{"t": "They block the mineralocorticoid receptor", "correct": true, "why": "Listed: mineralocorticoid (MR) receptor antagonists, potassium-sparing diuretics; site: collecting duct of the nephron."}, {"t": "They inhibit renin in the blood stream", "correct": false, "why": "That is aliskiren."}, {"t": "They block AT1 receptors in the blood stream", "correct": false, "why": "That is the angiotensin II receptor blockers."}, {"t": "They cause hypokalemia", "correct": false, "why": "They are potassium-sparing; hyperkalemia is listed."}], "teach": "Spironolactone and eplerenone are aldosterone antagonists at the mineralocorticoid receptor (MR) in the collecting duct. Aldosterone normally increases production of Na+/K+ channels and pumps; blocking it gives less Na+ reabsorption. Listed reactions: hyperkalemia, diarrhea, drowsiness, and in males gynecomastia and impotence.", "quote": "Spironolactone, Eplerenone: Potassium-sparing diuretic; Mineralocorticoid (MR) receptor antagonist; Kidney → Collecting duct of nephron; Hyperkalemia, diarrhea, drowsiness; Males: gynecomastia & impotence", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9–10"},
{"id": "DL2-087", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "group-hyperkalemia", "tags": ["drug-list", "list"], "source": "slide", "fg": "classes", "multi": true, "stem": "Which renin–angiotensin–aldosterone system (RAAS) drugs are listed with hyperkalemia as an adverse reaction? Select all that apply.", "options": [{"t": "Ramipril", "correct": true, "why": "Angiotensin-converting enzyme (ACE) inhibitor: hyperkalemia listed."}, {"t": "Valsartan", "correct": true, "why": "Angiotensin II receptor blocker (ARB): hyperkalemia listed."}, {"t": "Eplerenone", "correct": true, "why": "Mineralocorticoid receptor antagonist: hyperkalemia listed."}, {"t": "Aliskiren", "correct": false, "why": "Aliskiren’s listed reactions are angioedema, hypotension, cough, headache, diarrhea and skin rash."}, {"t": "Metoprolol", "correct": false, "why": "In the RAAS section metoprolol is listed for less renin production; no hyperkalemia is listed."}], "teach": "Hyperkalemia is listed for the ACE inhibitors, the angiotensin II receptor blockers and the mineralocorticoid receptor antagonists (potassium-sparing diuretics). It is not listed for aliskiren.", "quote": "ACE inhibitor: … hyperkalemia … ARB: Hyperkalemia, angioedema. Spironolactone/Eplerenone: Hyperkalemia, diarrhea, drowsiness", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8–10"},
{"id": "DL2-088", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "metoprolol-renin", "tags": ["drug-list", "apply"], "source": "slide", "fg": "classes", "stem": "How does metoprolol lower renin–angiotensin–aldosterone system (RAAS) activity?", "options": [{"t": "It blocks renal β1, so less renin is made", "correct": true, "why": "Listed: selective β1 blocker; site kidney; less renin production."}, {"t": "It inhibits angiotensin-converting enzyme", "correct": false, "why": "That is the ACE inhibitors."}, {"t": "It blocks the mineralocorticoid receptor", "correct": false, "why": "That is spironolactone and eplerenone."}, {"t": "It inhibits renin directly in the blood stream", "correct": false, "why": "Direct renin inhibition is aliskiren."}], "teach": "The RAAS section lists metoprolol, a selective β1 blocker, with the kidney as its site: blocking β1 there means less renin production, so the renin–angiotensin–aldosterone pathway is not started. The adrenergic section lists decreased RAAS among the effects of the β1 blockers.", "quote": "Metoprolol: Selective β1 blocker; Kidney; Less renin production → no RAAS pathway", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 10"}
);
